<?php
require_once __DIR__.'/auth.php';
if (admin_logged_in()) { header('Location: index.php'); exit; }
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') { try { $u=trim($_POST['username']??''); $p=$_POST['password']??''; $st=db()->prepare('SELECT * FROM admins WHERE username=? LIMIT 1'); $st->execute([$u]); $a=$st->fetch(); if($a && password_verify($p,$a['password_hash'])) { session_regenerate_id(true); $_SESSION['admin_id']=$a['id']; $_SESSION['admin_username']=$a['username']; header('Location: index.php'); exit; } $error='Invalid username or password. If this is a fresh installation, open reset_admin.php once.'; } catch (Throwable $e) { $error='Database error: '.$e->getMessage(); } }
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login — Strata &amp; Beam Engineering</title><meta name="robots" content="noindex, nofollow"><link href="https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Karla:wght@400;500;700&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet"><link rel="stylesheet" href="../assets/css/admin.css"><style>body{display:grid;place-items:center;min-height:100vh}</style></head><body><div class="box"><h1>Admin Login</h1><p class="muted" style="margin-bottom:20px;">Strata &amp; Beam Engineering — content management</p><?php if($error):?><div class="err"><?php echo htmlspecialchars($error);?></div><?php endif;?><form method="post"><label>Username</label><input name="username" required autofocus><label>Password</label><input name="password" type="password" required><button style="width:100%;text-align:center;">Log In</button></form><p style="margin-top:20px;"><a href="../index.php" class="muted">&larr; Back to website</a></p></div></body></html>
